create type public.app_role as enum ('admin','user');
create table public.user_roles (id uuid primary key default gen_random_uuid(), user_id uuid not null unique, role public.app_role not null default 'user');
grant select on public.user_roles to authenticated; grant all on public.user_roles to service_role; alter table public.user_roles enable row level security; create policy own_roles on public.user_roles for select to authenticated using (user_id=auth.uid());
create function public.has_role(_user_id uuid,_role public.app_role) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.user_roles where user_id=_user_id and role=_role)$$; grant execute on function public.has_role(uuid,public.app_role) to authenticated;
create table public.profiles (id uuid primary key, display_name text, avatar_url text, timezone text not null default 'UTC', theme text not null default 'dark', notifications jsonb not null default '{"new_anime":true,"date_changed":true,"new_episode":true,"upcoming":true,"delay":true}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now()); grant select,insert,update on public.profiles to authenticated; grant all on public.profiles to service_role; alter table public.profiles enable row level security; create policy own_profile on public.profiles for all to authenticated using (id=auth.uid()) with check (id=auth.uid());
create table public.animes (id uuid primary key default gen_random_uuid(), anilist_id integer unique, mal_id integer, title_romaji text not null, title_english text, title_native text, synonyms text[] not null default '{}', search_keys text[] not null default '{}', cover_url text, synopsis text, genres text[] not null default '{}', studio text, platforms text[] not null default '{}', season text, release_at timestamptz, date_confirmed boolean not null default false, airing_at timestamptz, status text, popularity integer, source_name text not null default 'AniList', source_url text, data_sources jsonb not null default '{}'::jsonb, first_detected_at timestamptz not null default now(), last_checked_at timestamptz not null default now(), updated_at timestamptz not null default now()); grant select on public.animes to anon,authenticated; grant all on public.animes to service_role; alter table public.animes enable row level security; create policy read_animes on public.animes for select to anon,authenticated using (true); create index animes_release_idx on public.animes(release_at);
create table public.saved_animes (user_id uuid not null, anime_id uuid not null references public.animes(id) on delete cascade, created_at timestamptz not null default now(), primary key(user_id,anime_id)); grant select,insert,delete on public.saved_animes to authenticated; grant all on public.saved_animes to service_role; alter table public.saved_animes enable row level security; create policy own_saved on public.saved_animes for all to authenticated using (user_id=auth.uid()) with check (user_id=auth.uid());
create table public.news_sources (id uuid primary key default gen_random_uuid(), name text not null, base_url text not null, enabled boolean not null default true, last_checked_at timestamptz, last_error text, created_at timestamptz not null default now(), updated_at timestamptz not null default now()); grant select on public.news_sources to anon,authenticated; grant all on public.news_sources to authenticated,service_role; alter table public.news_sources enable row level security; create policy read_news_sources on public.news_sources for select to anon,authenticated using (true); create policy admin_news_sources on public.news_sources for all to authenticated using (public.has_role(auth.uid(),'admin')) with check (public.has_role(auth.uid(),'admin'));
create table public.discoveries (id uuid primary key default gen_random_uuid(), anime_id uuid references public.animes(id) on delete cascade, title text not null, source_name text not null, source_url text, detected_at timestamptz not null default now(), last_checked_at timestamptz not null default now(), details jsonb not null default '{}'::jsonb); grant select on public.discoveries to authenticated; grant all on public.discoveries to service_role; alter table public.discoveries enable row level security; create policy admin_discoveries on public.discoveries for select to authenticated using (public.has_role(auth.uid(),'admin'));
create table public.anime_changes (id uuid primary key default gen_random_uuid(), anime_id uuid not null references public.animes(id) on delete cascade, field text not null, old_value jsonb, new_value jsonb, source_name text not null, conflict boolean not null default false, created_at timestamptz not null default now()); grant select on public.anime_changes to authenticated; grant all on public.anime_changes to service_role; alter table public.anime_changes enable row level security; create policy admin_anime_changes on public.anime_changes for select to authenticated using (public.has_role(auth.uid(),'admin'));
create table public.sync_runs (id uuid primary key default gen_random_uuid(), trigger text not null, status text not null default 'running', stats jsonb not null default '{}'::jsonb, errors jsonb not null default '[]'::jsonb, started_at timestamptz not null default now(), finished_at timestamptz); grant select on public.sync_runs to anon,authenticated; grant all on public.sync_runs to service_role; alter table public.sync_runs enable row level security; create policy read_sync_runs on public.sync_runs for select to anon,authenticated using (true); create unique index single_running_sync on public.sync_runs ((true)) where status='running';
create table public.video_animes (id uuid primary key default gen_random_uuid(), anime_id uuid references public.animes(id) on delete set null, title text not null, cover_url text, synopsis text, status text not null default 'airing' check(status in ('airing','finished')), episodes_total integer, external_slug text, source_name text, youtube_playlist_id text, last_synced_at timestamptz, last_sync_error text, updated_at timestamptz not null default now(), created_at timestamptz not null default now(), unique(source_name,external_slug)); grant select on public.video_animes to anon,authenticated; grant all on public.video_animes to service_role; alter table public.video_animes enable row level security; create policy read_video_animes on public.video_animes for select to anon,authenticated using (true);
create table public.video_episodes (id uuid primary key default gen_random_uuid(), video_anime_id uuid not null references public.video_animes(id) on delete cascade, number numeric not null, title text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(video_anime_id,number)); grant select on public.video_episodes to anon,authenticated; grant all on public.video_episodes to service_role; alter table public.video_episodes enable row level security; create policy read_video_episodes on public.video_episodes for select to anon,authenticated using (true);
create table public.video_sources (id uuid primary key default gen_random_uuid(), episode_id uuid not null references public.video_episodes(id) on delete cascade, label text not null, kind text not null check(kind in ('iframe','youtube','external')), url text not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(episode_id,url)); grant select on public.video_sources to anon,authenticated; grant all on public.video_sources to service_role; alter table public.video_sources enable row level security; create policy read_video_sources on public.video_sources for select to anon,authenticated using (true);
create table public.video_sources_catalog (id uuid primary key default gen_random_uuid(), name text not null, base_url text not null unique, kind text not null check(kind in ('iframe','youtube','external')), enabled boolean not null default true, last_checked_at timestamptz, last_error text, created_at timestamptz not null default now(), updated_at timestamptz not null default now()); grant select on public.video_sources_catalog to anon,authenticated; grant all on public.video_sources_catalog to authenticated,service_role; alter table public.video_sources_catalog enable row level security; create policy read_video_catalog on public.video_sources_catalog for select to anon,authenticated using (true); create policy admin_video_catalog on public.video_sources_catalog for all to authenticated using (public.has_role(auth.uid(),'admin')) with check (public.has_role(auth.uid(),'admin'));
create table public.video_changes (id uuid primary key default gen_random_uuid(), video_anime_id uuid not null references public.video_animes(id) on delete cascade, kind text not null check(kind in ('episode_added','source_changed')), old_value jsonb, new_value jsonb, source_name text, created_at timestamptz not null default now()); grant select on public.video_changes to authenticated; grant all on public.video_changes to service_role; alter table public.video_changes enable row level security; create policy admin_video_changes on public.video_changes for select to authenticated using (public.has_role(auth.uid(),'admin'));
create function public.set_updated_at() returns trigger language plpgsql set search_path=public as $$begin new.updated_at=now(); return new; end$$; create trigger profiles_updated before update on public.profiles for each row execute function public.set_updated_at(); create trigger animes_updated before update on public.animes for each row execute function public.set_updated_at(); create trigger video_animes_updated before update on public.video_animes for each row execute function public.set_updated_at(); create trigger video_episodes_updated before update on public.video_episodes for each row execute function public.set_updated_at(); create trigger video_sources_updated before update on public.video_sources for each row execute function public.set_updated_at(); create trigger video_catalog_updated before update on public.video_sources_catalog for each row execute function public.set_updated_at(); create trigger news_sources_updated before update on public.news_sources for each row execute function public.set_updated_at();